const http = require('http');
const WebSocket = require('ws');
const { Pool } = require('pg');
const { CameraRelayService } = require('../services/cameraRelay');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const server = http.createServer();
const wss = new WebSocket.Server({ server });

wss.on('connection', (ws, req) => {
  const userId = req.headers['x-user-id'];
  if (!userId) {
    ws.close(4401, 'Unauthenticated');
    return;
  }

  ws.on('message', async (msg) => {
    const payload = JSON.parse(msg);
    if (payload.command === 'START_CAMERA_STREAM') {
      const { cameraId } = payload;

      // Verify camera registration matches authenticated user
      const camCheck = await pool.query(
        'SELECT 1 FROM registered_cameras WHERE camera_id = $1 AND owner_user_id = $2',
        [cameraId, userId]
      );

      if (camCheck.rowCount === 0) {
        ws.send(JSON.stringify({ error: 'Forbidden: unauthorized camera stream' }));
        return;
      }

      try {
        await CameraRelayService.pipeRtspToWs(cameraId, ws);
      } catch (err) {
        ws.send(JSON.stringify({ error: 'Stream failed' }));
      }
    }
  });
});

server.listen(8002);
